def pthroot_xxt(x: jax.Array, scale: jax.Array | None = None) -> jax.Array:
  return (x if scale is None else x * scale) @ x.T

def _scalar_power(x: jax.Array, n: int) -> jax.Array:
  if n == 1:
    return x
  elif n % 2 == 0:
    return _scalar_power(x * x, n // 2)
  else:
    return x * _scalar_power(x * x, (n - 1) // 2)

def _scalar_inverse_root(x: jax.Array, n: int) -> jax.Array:
  if n == 1:
    return 1 / x
  elif n == 2:
    return jax.lax.rsqrt(x)
  elif n == 3:
    return 1 / jax.lax.cbrt(x)
  elif n == 4:
    return jax.lax.rsqrt(jax.lax.sqrt(x))
  elif n == 6:
    return jax.lax.rsqrt(jax.lax.cbrt(x))
  elif n == 8:
    return jax.lax.rsqrt(jax.lax.sqrt(jax.lax.sqrt(x)))
  else:
    r = x**(1 / n)
    r = ((n - 1) / n) * r + (x / n) / _scalar_power(r, n - 1)
    return 1 / r

