def safe_chol(m):
  l_m = jnp.linalg.cholesky(m)
  l_m = jnp.where(jnp.any(jnp.isnan(l_m)), jnp.zeros_like(l_m), l_m)
  return l_m

def chol_inv(m):
  eye = jnp.identity(m.shape[-1], dtype=jnp.float32)
  l_m = jnp.linalg.cholesky(m)
  def _get_inv():
    d_m = jax.lax.linalg.triangular_solve(l_m, eye, left_side=True, lower=True, transpose_a=False)
    return pthroot_xxt(d_m.T)
  def _get_zeros():
    return jnp.zeros_like(m)
  return jax.lax.cond(jnp.any(jnp.isnan(l_m)), _get_zeros, _get_inv)

