class NthPowerState(NamedTuple):
  pass # Empty state

def nth_power(power: Union[int, Tuple[int]] = 2) -> optax.GradientTransformation:
  if not hasattr(power, '__iter__'):
    power = [power]
  for p in power:
    if p != int(p):
      raise ValueError(f'Currently we only support integer orders; got {p}.')
  def init_fn(params: optax.Params) -> optax.OptState:
    del params
    return NthPowerState()
  def update_fn(updates: optax.Updates, state: optax.OptState, params: Optional[optax.Params] = None) -> Tuple[optax.Updates, optax.OptState]:
    del params
    for p in power:
      if p == 1:
        updates['variables'][str(int(p))] = updates['updates']
      else:
        gradients = jax.tree.map(lambda x: x**p, updates['updates'])
        updates['variables'][str(int(p))] = gradients
    return updates, state
  return optax.GradientTransformation(init_fn, update_fn)

class EmaAccumulatorState(NamedTuple):
  moments: optax.Updates
  count: jax.Array

def ema_accumulator(decay: float = 0.999, debias: bool = False) -> optax.GradientTransformation:
  def init_fn(params: optax.Params) -> optax.OptState:
    return (jax.tree.map(jnp.zeros_like, params), jnp.array(0, dtype=jnp.int32))
  def update_fn(updates: optax.Updates, state: optax.OptState, params: Optional[optax.Params] = None) -> Tuple[optax.Updates, optax.OptState]:
    del params
    moments, count = state
    update_fn = lambda g, t: (1 - decay) * g + decay * t
    moments = jax.tree.map(update_fn, updates['variables'], moments)
    count = count + jnp.array(1, dtype=jnp.int32)
    beta = jnp.array(1, dtype=jnp.int32) - decay**count
    updates['moments'] = moments if not debias else jax.tree.map(lambda t: t / beta.astype(t.dtype), moments)
    return updates, (moments, count)
  return optax.GradientTransformation(init_fn, update_fn)

